use std::time::Instant;
use superstring::SimulatedAnnealing;

fn main() {
    let days = days_in_year(true);
    // let start = Instant::now();
    // let superstring = shortest_super_string(days);
    // println!("{}", superstring);
    // println!("{}ms", start.elapsed().as_millis());
    let start = Instant::now();
    let mut solver = SimulatedAnnealing::load_or_restart("days365.json", days).with_template(1e+8, 1e-8, 0.9);
    let superstring = solver.short_super_string();
    println!("{}", superstring);
    println!("{} in {}ms", superstring.len(), start.elapsed().as_millis());
}

// 
// 
// 
// 010816052061407301207081028

pub fn days_in_year(leap_year: bool) -> Vec<String> {
    let days_in_month = vec![31, if leap_year { 29 } else { 28 }, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
    let mut days = Vec::new();
    for (month, &days_in_month) in days_in_month.iter().enumerate() {
        for day in 1..=days_in_month {
            days.push(format!("{:02}{:02}", month + 1, day));
        }
    }
    days
}
